(function(root){function journeyProgress(times,now,boardId,riding=false,destinationId){let board=times.find(t=>t.stopId===boardId),end=times.find(t=>t.stopId===destinationId)||times.at(-1),origin=times[0];if(!board||!end||!origin)return {fraction:0,remaining:null,phase:'unavailable'};let start=riding?board.expectedDeparture:origin.expectedDeparture,finish=riding?end.expectedArrival:board.expectedArrival;let fraction=finish>start?Math.max(0,Math.min(1,(now-start)/(finish-start))):now>=finish?1:0;return {fraction,remaining:Math.max(0,Math.ceil(finish-now)),phase:riding?(now>=finish?'arrived':'riding'):(now>=finish?'at-stop':'approaching')}}function arcPoint(fraction){let f=Number.isFinite(fraction)?Math.max(0,Math.min(1,fraction)):0;let points=[],length=0;for(let i=0;i<=160;i++){let t=i/160,u=1-t,x=u*u*u*20+3*u*u*t*35+3*u*t*t*285+t*t*t*300,y=u*u*u*104+3*u*u*t*(-10)+3*u*t*t*(-10)+t*t*t*104;if(i)length+=Math.hypot(x-points[i-1].x,y-points[i-1].y);points.push({x,y,length})}let target=length*f;for(let i=1;i<points.length;i++){let a=points[i-1],b=points[i];if(b.length>=target){let ratio=(target-a.length)/(b.length-a.length);return {x:a.x+(b.x-a.x)*ratio,y:a.y+(b.y-a.y)*ratio}}}return {x:300,y:104}}let api={journeyProgress,arcPoint};root.MetroProgress=api;if(typeof module!=='undefined')module.exports=api})(globalThis);
